def close(self) -> None:
    """Invoke all close callbacks registered with
    :meth:`call_on_close`, and exit all context managers entered
    with :meth:`with_resource`.

    If :attr:`cleanup_timeout` is set, cleanup is abandoned when it
    exceeds that duration and a warning is printed.  This prevents
    unresponsive cleanup operations from hanging the process.

    .. versionchanged:: 8.3
        Added the timeout enforced by :attr:`cleanup_timeout`.
    """
    if self.cleanup_timeout is None:
        self._exit_stack.close()
    else:
        deadline = time.monotonic() + self.cleanup_timeout
        interrupted = False

        try:
            self._exit_stack.close()
        except BaseException as e:
            if (
                isinstance(e, TimeoutError)
                and "cleanup" in str(e).lower()
            ):
                interrupted = True
            else:
                raise
        finally:
            remaining = deadline - time.monotonic()

            if remaining < 0 and not interrupted:
                interrupted = True

            if interrupted:
                echo(
                    "Warning: context cleanup timed out after "
                    f"{self.cleanup_timeout} seconds; "
                    "remaining cleanup operations were skipped.",
                    err=True,
                )

    # In case the context is reused, create a new exit stack.
    self._exit_stack = ExitStack()

